    seq: {
        "name": window["name"],
        "size": window["size"],
        "sha256": window["sha256"],
    }
    for seq, window in enumerate(emitted)
}
return {
    "tenant": tenant,
    "start": start,
    "end": end,
    "count": total,
    "prev": predecessor if predecessor is not None else "",
    "anchors": anchors,
    "buckets": [
        {"seq": seq, "records": window["records"]}
        for seq, window in enumerate(emitted)
    ],
}

